head.script:
scwin.checkVal = function() {
    return WebSquare.wUnit.getObjById("wq_uuid_4").getValue() == '12.34';
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 1. 샘플을 실행 후 "maxByteLength2"의 입력값에 값을 입력한다.(예 : 12.3456)
    //1. After running the sample, enter a value for the input value of 'maxByteLength2' (for example, 12.3456).
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('wq_uuid_4').focus()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('wq_uuid_4').setValue(12.3456)");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('wq_uuid_4').blur()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 1. 결과값으로 12.34까지만 입력되어진다.
    //1. Only results up to 12.34 are entered.
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //Function unitTest
    //Create buy Truong.Luu
    //Create date 07-Mar-2018
    //End unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
